// Offline verification for the vendored boot-screen runtime.
//
// No DSH process, no ports, no network, no prompts — and no sibling checkout
// either: this suite asserts the SHIPPED artifact, so it runs from the package
// alone. Run from the package root:
//   node verify/verify-splash-vendor.mjs
//
// The runtime under assets/splash/ is generated by tools/vendor-splash-runtime.mjs
// from two upstream trees (dsh-boot-suite, and dsh-startup-screen for the glass
// treatment). This suite is the contract that generation must keep satisfying:
// the renames that isolate this plugin from the others, the pieces the Host's
// injection rows depend on, and the things that must NOT have been renamed —
// the .dsu-* class vocabulary and the postMessage names an iframe template
// speaks. A rename applied to the wrong side of that line breaks a screen with
// no error anywhere, which is why every one of them is asserted here.

import { readFileSync, existsSync, statSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { validateTemplate } from '../src/template-validate.js'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const splash = join(root, 'assets', 'splash')

let failures = 0
let checks = 0

function check(label, condition, detail) {
  checks++
  console.log((condition ? '  ok   ' : '  FAIL ') + label
    + (detail === undefined || detail === '' ? '' : '   [' + detail + ']'))
  if (!condition) failures++
  return condition
}

/** Strip line and block comments — the banner legitimately names what it replaced. */
function stripComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/[^\n]*/g, '$1')
}

const runtime = readFileSync(join(splash, 'splash.js'), 'utf8')
const runtimeCode = stripComments(runtime)
const sheet = readFileSync(join(splash, 'splash.css'), 'utf8')

// ---------------------------------------------------------------------------
// 1. It parses, and the artifact is complete.
// ---------------------------------------------------------------------------

console.log('\n[1] the artifact')
// Compiled rather than spawned: `new Function` runs the same parser node
// --check would, without a child process — and a suite that needs a shell to
// prove a file parses is a suite that cannot run everywhere.
try {
  new Function(runtime)
  check('the runtime parses', true)
} catch (error) {
  check('the runtime parses', false, String(error.message).split('\n')[0])
}
check('the stylesheet is non-trivial', sheet.length > 40000, String(sheet.length) + ' chars')
check('the banner documents the vendoring',
  runtime.includes('VENDORED + ADAPTED') && runtime.includes('dsh-boot-suite')
  && runtime.includes('dsh-startup-screen'))
for (const name of ['sfx-tick.mp3', 'sfx-ticks-run.mp3']) {
  check('sound effect ships: ' + name, existsSync(join(splash, 'assets', name)))
}
check('the voice manifest ships', existsSync(join(splash, 'voices', 'manifest.json')))
const packs = ['f', 'g', 'h', 'i', 'j', 'k']
check('all six voice packs ship',
  packs.every((pack) => existsSync(join(splash, 'voices', pack, 'line-1.mp3'))))

// ---------------------------------------------------------------------------
// 2. The renames that isolate this plugin from the other two.
// ---------------------------------------------------------------------------

console.log('\n[2] isolation renames (code only — the banner may name them)')
for (const [label, pattern] of [
  ['no __DSH_STARTUP global survives in code', /__DSH_STARTUP/],
  ['no /dsh-startup route survives in code', /\/dsh-startup/],
  ['no dsh-startup-root id survives in code', /dsh-startup-root/],
]) {
  check(label, pattern.test(runtimeCode) === false)
}
check('no old storage key survives in code', !runtimeCode.includes('dsh-startup-screen:shown')
  && !runtimeCode.includes('dsh-startup-screen:day'))

equal('the config global', globalOf(runtimeCode, '__DSH_BOOT_ANIM_TPL_CFG__') !== undefined, true)
equal('the template globals',
  [globalOf(runtimeCode, '__DSH_BOOT_ANIM_TPL_1__') !== undefined,
    globalOf(runtimeCode, '__DSH_BOOT_ANIM_TPL_2__') !== undefined], [true, true])
check('the API global is the plugin\'s own',
  runtimeCode.includes('window.__DSH_BOOT_ANIM_TPL_API__'))
check('the skip and loaded guards are the plugin\'s own',
  runtimeCode.includes('window.__DSH_BOOT_ANIM_TPL_SKIP__')
  && runtimeCode.includes('window.__DSH_BOOT_ANIM_TPL_LOADED__'))
check('the running flag the bootstrap waits on is set in run()',
  /runStarted = true\n\s*try \{ window\.__DSH_BOOT_ANIM_TPL_RUNNING__ = true \}/.test(runtimeCode))
check('the storage keys are the plugin\'s own',
  runtimeCode.includes("'dsh-boot-animation:tpl-shown'")
  && runtimeCode.includes("'dsh-boot-animation:tpl-day'"))
check('the completion event is the plugin\'s own',
  runtimeCode.includes("'dsh-boot-animation:tpl-done'"))

/** The literal name a global is read or written under, if the code has one. */
function globalOf(code, name) {
  const at = code.indexOf('window.' + name)
  if (at < 0) return undefined
  return code.slice(at, at + name.length + 8)
}

function equal(label, actual, expected) {
  const a = JSON.stringify(actual)
  const e = JSON.stringify(expected)
  return check(label, a === e, a === e ? a : 'actual ' + a + ' != expected ' + e)
}

// ---------------------------------------------------------------------------
// 3. The pieces the Host's injection rows and routes depend on.
// ---------------------------------------------------------------------------

console.log('\n[3] the Host\'s contract with the runtime')
check('the route prefix resolves from the injected global',
  /var BASE = \(function \(\) \{[\s\S]{0,200}__DSH_BOOT_ANIM_TPL_BASE__/.test(runtimeCode))
check('...with this package\'s prefix as the literal fallback',
  runtimeCode.includes("|| '/plugins/dsh-boot-animation/tpl'"))
for (const route of ['/splash.js', '/voice/', '/asset/', '/template-asset/', '/frame-session',
  '/template-frame/', '/template-file/', '/diag', '/music/file']) {
  check('the runtime fetches ' + route + ' through BASE', runtimeCode.includes("BASE + '" + route))
}
check('the mount id matches the injection row',
  runtimeCode.includes("var ROOT_ID = 'dsh-boot-anim-tpl'"))
check('the caption probe id matches the bootstrap\'s',
  runtimeCode.includes("'dsh-boot-anim-tpl-caption'"))
check('the replay path rebuilds through BASE rather than a hardcoded route',
  runtimeCode.includes("BASE + '/splash.js?t='"))

// ---------------------------------------------------------------------------
// 4. What must NOT have been renamed.
// ---------------------------------------------------------------------------

console.log('\n[4] what the rename must leave alone')
for (const name of ['dsh-startup-done', 'dsh-startup-skip', 'dsh-startup-voice', 'dsh-startup-bgm']) {
  // The postMessage vocabulary an iframe template speaks. Renaming it here
  // would break every template imported from the source tree, which honours
  // the documented contract.
  check('postMessage name kept: ' + name, runtimeCode.includes("'" + name + "'"))
}
check('the .dsu-* class vocabulary is intact',
  runtimeCode.includes("'dsu-root'") && runtimeCode.includes("'dsu-boot'")
  && runtimeCode.includes("'dsu-glass'"))
check('the stylesheet still styles the .dsu-* vocabulary',
  sheet.includes('.dsu-plate') && sheet.includes('.dsu-black') && sheet.includes('.dsu-wash'))

// ---------------------------------------------------------------------------
// 5. The ported glass treatment.
// ---------------------------------------------------------------------------

console.log('\n[5] the ported glass treatment')
check('the config keys are declared', /glass: false/.test(runtimeCode)
  && /glassOpacity: 0\.75/.test(runtimeCode) && /glassBackdropBlur: 28/.test(runtimeCode))
check('the block is guarded by the setting', /if \(C\.glass\) \{/.test(runtimeCode))
check('the backdrop blur and its restore both exist',
  runtimeCode.includes('function blurAppBackdrop(px)')
  && runtimeCode.includes('function restoreAppBackdrop()'))
check('...and the restore is called from finish()',
  /invalidateRun\(\)[^\n]*\n\s*try \{ restoreAppBackdrop\(\) \}/.test(runtimeCode))
check('the stylesheet carries the glass rules',
  sheet.includes('#dsh-boot-anim-tpl.dsu-glass') && sheet.includes('.dsu-glass .dsu-plate')
  && sheet.includes('@keyframes dsu-glass-drift') && sheet.includes('.dsu-backdrop'))
check('glass is off by default in the Host schema too',
  readFileSync(join(root, 'entry.js'), 'utf8').includes('glass: false'))

// ---------------------------------------------------------------------------
// 6. Stylesheet hygiene the project learned the hard way.
// ---------------------------------------------------------------------------

console.log('\n[6] stylesheet hygiene')
check('no unquoted numeric attribute selector in the sheet',
  !/\[[a-zA-Z-]+=[0-9]/.test(sheet))
check('the sheet names the plugin\'s own root id',
  sheet.includes('#dsh-boot-anim-tpl') && !sheet.includes('#dsh-startup-root'))
check('reduced-motion is honoured for the glass drift',
  /@media \(prefers-reduced-motion: reduce\) \{\s*\.dsu-glass::after \{ animation: none; \}/.test(sheet))

// ---------------------------------------------------------------------------
// 7. Every shipped template still validates against the module that guards it.
// ---------------------------------------------------------------------------

console.log('\n[7] the templates the runtime will be asked to play')
const templatesDir = join(root, 'assets', 'templates')
const { readdirSync } = await import('node:fs')
let validated = 0
for (const entry of readdirSync(templatesDir, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue
  const file = join(templatesDir, entry.name, 'template.json')
  if (!existsSync(file)) continue
  const checked = validateTemplate(JSON.parse(readFileSync(file, 'utf8')))
  check('template "' + entry.name + '" validates', checked.ok === true, checked.reason ?? '')
  if (checked.ok) validated += 1
}
check('at least ten templates ship', validated >= 10, String(validated))

// ---------------------------------------------------------------------------
// 8. The vendored editor page.
// ---------------------------------------------------------------------------

console.log('\n[8] the vendored editor')
const editor = existsSync(join(root, 'assets', 'editor', 'editor.html'))
  ? readFileSync(join(root, 'assets', 'editor', 'editor.html'), 'utf8')
  : ''
check('the editor ships', editor.length > 100000, String(editor.length) + ' chars')
check('...built from this package\'s routes',
  editor.includes("var API = '/plugins/dsh-boot-animation/tpl'"))
check('...with the /config-shaped replaces rewritten to plain concatenation',
  editor.includes("API + '/template-assets/upload'")
  && editor.includes("API + '/template-asset/'")
  && !editor.includes("'/config'"))
check('...and no stale route prefix anywhere', !editor.includes('/dsh-startup'))
check('...and its idcard reference points at this package',
  editor.includes('/plugins/dsh-boot-animation/tpl/idcard'))
check('the editor is LF, like the rest of the tree', !editor.includes('\r\n'))

console.log('\n' + (failures === 0 ? 'PASS' : 'FAIL') + ' — '
  + String(checks - failures) + '/' + String(checks) + ' checks')
if (failures > 0) process.exitCode = 1
